INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(3372, 'plPL', 'Uwolnij ich', 'Uwolnij ich, $N. Nawet gdy ich ciała odmawiają posłuszeństwa, moc Suntary zmusza ich do wykonywania zadań.$B$BKluczem jest ołtarz Suntary. Idź na północny zachód; na wzgórzach nad jaskinią... Młot Zmierzchu strzeże reliktu. Zdobądź go i połóż na ołtarzu Suntary.$B$B<Umierający archeolog osuwa się na ziemię.>', 'Odnajdź tajemniczy artefakt strzeżony przez bałwochwalczynie Młota Zmierzchu w północno-zachodniej części Płonącego Wąwozu i zanieś go do Ołtarza Suntary w Żużlowej Czeluści.$B', '', 'Wróć do Ołtarza Suntary na Grani Ognistej Straży w Płonącym Wąwozie.', '', '', '', '', 0),
(3379, 'plPL', 'Tkaczka cienia', 'Pająki Płonącego Wąwozu są bezcennym źródłem jedwabiu cienia. Jak wiesz, rzemieślnicy naszego fachu bardzo go pożądają.$B$BOstatnio na te ziemie wtargnęła grupa kłusowników, którzy bezmyślnie wybijają pająki masowo, nie zastanawiając się nawet przez chwilę nad długofalowymi skutkami swoich czynów. Pierwsze zadanie, o które cię proszę, jest więc proste: znajdź ich... i skończ z nimi.$B$BZacznij poszukiwania na północy.$B$BJeśli potrzebujesz pomocy, porozmawiaj z Raze\'em.', 'Zabij grupę kłusowników Cienistego Jedwabiu, którzy wędrują po Płonącym Wąwozie. Nilith ma powody sądzić, że trzeba wytępić pięciu z nich. Gdy wykonasz to zadanie, wróć do Nilith w Płonącym Wąwozie.$B', '', 'Wróć do Nilith Lokrav w Płonącym Wąwozie.', '', '', '', '', 0),
(3385, 'plPL', 'Podziemny Targ', 'Nazywają siebie Podziemnym Targiem: bezwzględni handlarze, którzy za odpowiednią cenę sprzedadzą, przewiozą, wymienią i zrobią właściwie wszystko.$B$BA to jeszcze nie najgorsze, $N. Założyli bazę wypadową tutaj, w Płonącym Wąwozie. Na czele całej operacji stoi mistrz handlu Kovic, który ma bliskie powiązania z miejscowymi Czarnorytymi.$B$BMusimy uderzyć mocno i przekazać wiadomość ich przywódcom. Zabij mistrza handlu Kovica i jego sługę Brzdęka. Gdy skończysz, przynieś jego torbę kupca.$B$BDo Kotła!', 'Zabij mistrza handlu Kovica i jego sługę Brzdęka. Zabierz torbę kupca z jego zwłok i zanieś ją Nilith.$B', '', 'Wróć do Nilith Lokrav w Płonącym Wąwozie.', '', '', '', '', 0),
(3441, 'plPL', 'Boski odwet', 'Wysłuchaj mojej opowieści, $gposzukiwaczu:poszukiwaczko; przygód.', 'Wysłuchaj opowieści Kalarana Wietrznego Ostrza.', 'Opowieść Kalarana', 'Wróć do Kalarana Wietrznego Ostrza w Kotle w Płonącym Wąwozie.', '', '', '', '', 0),
(3442, 'plPL', 'Nieskazitelny płomień', '$GPodjąłeś:Podjęłaś; słuszną decyzję, $N.$B$BMusimy uderzyć tam, gdzie wyrządzimy najwięcej szkód: w cztery wieże wartownicze.$B$BGdy cztery wieże staną w płomieniach, będziemy mogli rozpocząć natarcie, zanim zdążą zareagować.$B$BDo podpalenia wież potrzebne ci będzie odpowiednie narzędzie. Aby je wykonać, trzeba zdobyć kilka materiałów.$B$BPrzynieś mi cztery serca płomienia i cztery porcje oleju golemów, a wykonam pochodnię nieskazitelnego płomienia.$B$BTwoim pierwszym celem powinny być golemy i żywiołaki z tych ziem.', 'Zbierz 4 serca płomienia i 4 kule oleju golemów, a następnie zanieś je Kalaranowi Wietrznemu Ostrzu.', '', 'Wróć do Kalarana Wietrznego Ostrza w Płonącym Wąwozie.', '', '', '', '', 0),
(3443, 'plPL', 'Wykuwanie drzewca', 'Aby utrzymać nieskazitelny płomień, potrzebujemy drzewca i osłony. Najpierw musisz znaleźć odpowiednie drzewce.$B$BNadzorcy i handlarze niewolników Czarnorytych w Kotle używają broni z zaklętego torium, niezwykle wytrzymałego stopu. Jeśli przyniesiesz mi osiem sztyletów platerowanych torium, rozłożę stop i przekuję go na drzewce.$B', 'Przynieś 8 sztyletów platerowanych torium Kalaranowi Wietrznemu Ostrzu.', '', 'Wróć do Kalarana Wietrznego Ostrza w Kotle w Płonącym Wąwozie.', '', '', '', '', 0),
(3452, 'plPL', 'Osłona płomienia', 'Potrzebujemy jeszcze jednej, ostatniej części, by uformować pochodnię.$B$BW górach na północnym zachodzie znajdziesz duży obóz Młota Zmierzchu. Podobno jego członkowie noszą symbole i bożki oddające cześć ich bogu. Te symbole i bożki mogą być nasycone zaklęciami na tyle, by posłużyć jako magiczna osłona. Przynieś mi jeden symbol Ragnarosa, a spróbuję wydobyć z niego magię i stworzyć osłonę.', 'Znajdź symbol Ragnarosa i zanieś go Kalaranowi Wietrznemu Ostrzu.', '', 'Wróć do Kalarana Wietrznego Ostrza w Płonącym Wąwozie.', '', '', '', '', 0),
(3453, 'plPL', 'Pochodnia odwetu', 'Daj mi chwilę, połączę części i nałożę potrzebne zaklęcia.$B', 'Zaczekaj, aż Kalaran Wietrzne Ostrze ukończy Pochodnię odwetu.$B', 'Tworzenie pochodni', 'Wróć do Kalarana Wietrznego Ostrza w Płonącym Wąwozie.', '', '', '', '', 0),
(3454, 'plPL', 'Pochodnia odwetu', 'Teraz pochodnia musi zostać związana ze swoim właścicielem. Podnieś pochodnię, $N.', 'Weź Pochodnię odwetu.', '', '', '', '', '', '', 0),
(3462, 'plPL', 'Giermek Maltrake', 'Porozmawiaj z moim posłańcem, giermkiem Maltrake\'em. Udzieli ci dalszych wskazówek, jak używać Pochodni odwetu.', 'Porozmawiaj z giermkiem Maltrake\'em.', '', '', '', '', '', '', 0),
(3463, 'plPL', 'Podpal je!', 'Słuchaj uważnie, $N. Choć czterech wież nie da się zniszczyć, możesz za pomocą pochodni odwetu podpalić je na bardzo długi czas: ogniem, którego nie ugasi żaden żywioł ani żadna siła.$B$BDopóki płoną, żaden strażnik ani wartownik nie może zająć posterunków, a tym samym ich pierwsza linia obrony przestaje istnieć.$B$BMusisz wejść do każdej wieży i użyć Pochodni odwetu w obrębie jej fortyfikacji. Strzeż się czujek wystawionych przez Czarnorytych, $N.', 'Podpal północną, południową, wschodnią i zachodnią wieżę wartowniczą, używając Pochodni odwetu wewnątrz każdego z budynków.$B', '', 'Wróć do giermka Maltrake\'a w Płonącym Wąwozie.', 'Zachodnia wieża w ogniu', 'Południowa wieża w ogniu', 'Wschodnia wieża w ogniu', 'Północna wieża w ogniu', 0),
(3481, 'plPL', 'Błyskotki...', 'Skrzynia wydaje się zamknięta.', 'Otwórz skrzynię.', '', '', '', '', '', '', 0),
(4449, 'plPL', 'Złapany!', 'Hej! Hej, ty! Chodź no tu!$B$BMusisz mi pomóc. Uciekałem przed tymi Czarnorytymi i schowałem się tu, żeby mnie nie widzieli. Przeklęci geolodzy i te ich magiczne sztuczki! Musieli widzieć, jak się chowam, bo zanim się obejrzałem, zamknęli drzwi i uwięzili mnie tutaj.$B$BDaj tym geologom nauczkę! Aha... i czy możesz mi załatwić trochę jedwabnego płótna do... do... do niczego.', 'Zabij 8 geologów Czarnorytych i przynieś 15 kawałków jedwabnego płótna osobie zamkniętej w wychodku w Płonącym Wąwozie.', '', 'Wróć do drewnianego wychodka na Bezludziu.', '', '', '', '', 0),
(4451, 'plPL', 'Klucz do wolności', 'Mały mosiężny kluczyk wygląda całkiem zwyczajnie. Wyróżniają go tylko słowa wydrapane na główce:$B$B„Wychodek Czarnorytych – nie dorabiać”.$B$BNie masz pojęcia, co to znaczy ani dokąd cię to zaprowadzi.', 'Przeszukaj Płonący Wąwóz i znajdź zastosowanie dla znalezionego klucza do wychodka z Brudnego Mułu.', '', '', '', '', '', '', 0),
(7701, 'plPL', 'POSZUKIWANY: nadzorca Maltorius', 'Na rozkaz jego ekscelencji, nadzorcy Olejnej Pięści: zdradziecki agent Bractwa Torium, a teraz nowo najęty dowódca załogi Czarnorytych z Żużlowej Czeluści w Kotle, nadzorca Maltorius, ma zostać zabity, a jego łeb przyniesiony jako dowód dokonania czynu.$B$BPo nagrodę za tę głowę zgłoś się do kapitana czujek Lolo Dalekociosa.', 'Głęboko w Żużlowej Czeluści w Kotle, w Płonącym Wąwozie, znajdziesz zdradzieckiego krasnoluda z klanu Czarnorytów – nadzorcę Maltoriusa.$B$BZabij nadzorcę Maltoriusa i zabierz jego głowę. Po nagrodę zanieś głowę kapitanowi czujek Lolo Dalekociosowi w Płonącym Wąwozie.', '', 'Wróć do kapitana czujek Lolo Dalekociosa w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7702, 'plPL', 'Zabić ich bezsennością', 'Jeśli chcemy nadszarpnąć wydajność sił Czarnorytych działających z Żużlowej Czeluści, musimy uderzyć tam, gdzie zaboli najbardziej.$B$BMało kto o tym wie, ale krasnoludy, zwłaszcza te z odmiany Czarnorytych, potrzebują odpoczynku! Mnóstwa odpoczynku!$B$BA teraz pytam cię: jak mają spać bez poduszek? Właśnie, $N, nie mogą. Dlatego musisz wkraść się do Żużlowej Czeluści i ukraść im poduszki.', 'Głęboko w Żużlowej Czeluści w Kotle znajdziesz sypialnie Czarnorytych.$B$BUdaj się do sypialni i ukradnij 20 poduszek Czarnorytych. Gdy to zrobisz, wróć do Evonice Sadzodymnej w Płonącym Wąwozie.', '', 'Wróć do Evonice Sadzodymnej w Kotle w Płonącym Wąwozie.', '', '', '', '', 0),
(7704, 'plPL', 'Patrz, jaka wielka!', 'No, no, no... A to niespodzianka. Pokojówka miała gigantyczną ozdobną poduszkę, a teraz jest ona twoja. Evonice Sadzodymna na pewno zechce położyć na niej swoje brudne łapki. Zanieś ją jej i sprawdź, czy da ci coś w zamian za fatygę.', 'Zanieś poduszkę pokojówki Ściskopoduchy Evonice Sadzodymnej w Płonącym Wąwozie.', '', '', '', '', '', '', 0),
(7722, 'plPL', 'Do jasnego topnika!', 'Kiedy ten zdrajca, Maltorius, odszedł z naszego klanu, zabrał ze sobą coś cenniejszego niż nieskazitelny kryształ arkanów: nasz przepis na ognisty topnik! Dam sobie głowę uciąć, że ten przepis był częścią umowy o jego nowy awans u Czarnorytych.$B$BChcę, żebyś $godzyskał:odzyskała; nasze tajne plany, $N. Na pewno są gdzieś przy Maltoriusie, głęboko w Żużlowej Czeluści.', 'Gdzieś w Żużlowej Czeluści w Kotle znajdziesz Tajne plany: ognisty topnik, które ukradł nadzorca Maltorius. Znajdź te plany i zanieś je mistrzowi kowalskiemu Spopielatorowi w Płonącym Wąwozie.$B', '', 'Wróć do mistrza kowalskiego Spopielatora w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7723, 'plPL', 'Przeklęte grube paluchy', 'Niestety nie mogę już rozdawać razów jak dawniej, a to przez te tu grube paluchy. Widzisz, tutejszy klimat, do tego brak ciśnienia powietrza, i palce mi puchną. Są jak wielkie kaszanki z Thelsamaru, słowo daję...$B$BBędziesz $gmusiał:musiała; załatwiać za mnie moje sprawy i co tam jeszcze.$B$BPierwsze na mojej liście: stłuc na kwaśne jabłko ciężkie golemy bojowe z Wąwozu. Do roboty.', 'Hansel Ciężkoręki chce, żebyś $gzabił:zabiła; 20 ciężkich golemów bojowych.$B$BCiężkie golemy bojowe wędrują po okolicach Kotła w Płonącym Wąwozie. Gdy zabijesz ich dość, wróć do Hansela w Płonącym Wąwozie.', '', 'Wróć do Hansela Ciężkorękiego w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7724, 'plPL', 'Ogniste zagrożenie!', 'No i proszę, za każdym razem, gdy stary Hansel chce chwilę odpocząć i zastanowić się nad swoim życiem, siły wyższe dają mu kolejną robotę.$B$BMuszę pomyśleć, no weź! Wiesz, co mówię? No. Weź.$B$BNo więc te tu większe pająki lawowe robią jakiś rwetes. Olejna Pięść mówi, że strzelają ogniem z... eee, no dobra, w każdym razie takie rzeczy denerwują dzieciaki.$B$BChyba musimy je zabić. A raczej ty musisz je zabić.', 'Hansel Ciężkoręki chce, żebyś $gzabił:zabiła; 20 większych pająków lawowych w Płonącym Wąwozie. Większe pająki lawowe znajdziesz na płaskowyżach i w jeziorkach lawy Płonącego Wąwozu.$B$BGdy zabijesz ich dość, wróć do Hansela Ciężkorękiego w Płonącym Wąwozie.', '', 'Wróć do Hansela Ciężkorękiego w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7727, 'plPL', 'Incendozaury? Raczej jakieśtamzaury', 'Haluksy, $gchłopcze:dziewczyno;. Moje haluksy mają haluksy. Jak mam kogokolwiek zabijać, kiedy moje stopy są w takim stanie? Dlatego ty mi pomożesz.$B$BScrange i Spopielator kazali mi wybić te stwory, żeby mogli posłać kilka ekip badawczych do jezior lawy w Żużlowej Czeluści. Podobno jakieś incendozaury czy inne bzdury sprawiają tam wszelkiej maści kłopoty. No to ruszaj i nie wracaj, dopóki incendozaury nie wyginą.', 'Hansel Ciężkoręki chce, żebyś $gzabił:zabiła; 20 incendozaurów.$B$BIncendozaury zajmują jeziora lawy w Żużlowej Czeluści. Żużlową Czeluść znajdziesz w Kotle w Płonącym Wąwozie.$B$BGdy zabijesz ich dość, wróć do Hansela Ciężkorękiego w Płonącym Wąwozie.', '', 'Wróć do Hansela Ciężkorękiego w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7728, 'plPL', 'SKRADZIONE: dysza kowalska i luneta czujki', 'Skradziono następujące przedmioty:$B$B*Jedną dyszę kowalską Czarnorytych.$B$B*Jedną lunetę czujki.$B$BZa odnalezienie i zwrot tych przedmiotów wyznaczono nagrodę.$B$BBractwo Torium jest pewne, że przedmioty ukradli pozbawieni skrupułów i zazdrośni Czarnoryci zamieszkujący Płonący Wąwóz.$B$BWspomniana luneta była doskonałym narzędziem czujek, a dysza – niezastąpionym narzędziem kowalskim.$B$BJeśli odnajdziesz zaginione przedmioty, zwróć je Scrange\'owi.', 'Odnajdź dyszę kowalską i lunetę czujki i zwróć je poganiaczowi Scrange\'owi w Płonącym Wąwozie.$B$BO tych przedmiotach wiesz tylko tyle: na pewno ukradli je Czarnoryci. Dysza kowalska to narzędzie używane przez kowali, a luneta czujki to bezcenne narzędzie obserwacyjne czujek.', '', 'Wróć do poganiacza Scrange\'a w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7729, 'plPL', 'OFERTA PRACY: przetrzebienie konkurencji', 'Poganiacz Scrange szuka kilku dzielnych mężczyzn i kobiet do pomocy w „przetrzebieniu konkurencji” w Płonącym Wąwozie.$B$BJeśli interesuje cię ta posada, wyrusz do Płonącego Wąwozu i wyrżnij każdego nadzorcę Czarnorytych i każdego handlarza niewolników Czarnorytych, jakiego zobaczysz.$B$BWróć do poganiacza Scrange\'a, gdy twoje ubranie będzie wystarczająco zakrwawione.$B$BBędziesz wiedzieć, kiedy będzie wystarczająco zakrwawione, więc nie pytaj.', 'Zabij 15 nadzorców Czarnorytych i 15 handlarzy niewolników Czarnorytych. Gdy to zrobisz, wróć do poganiacza Scrange\'a w Płonącym Wąwozie.', '', 'Wróć do poganiacza Scrange\'a w Punkcie Torium w Płonącym Wąwozie.', '', '', '', '', 0),
(7736, 'plPL', 'Uzupełnianie ognistego topnika: królewska krew', '', '', '', 'Wróć do mistrza kowalskiego Spopielatora w Płonącym Wąwozie.', '', '', '', '', 0),
(7737, 'plPL', 'Jeszcze więcej uznania', '', '', '', 'Wróć do mistrza kowalskiego Spopielatora w Płonącym Wąwozie.', '', '', '', '', 0),
(8241, 'plPL', 'Uzupełnianie ognistego topnika: żelazo', '', '', '', 'Wróć do mistrza kowalskiego Spopielatora w Płonącym Wąwozie.', '', '', '', '', 0),
(8242, 'plPL', 'Uzupełnianie ognistego topnika: ciężka skóra', '', '', '', 'Wróć do mistrza kowalskiego Spopielatora w Płonącym Wąwozie.', '', '', '', '', 0),
(8651, 'plPL', 'Nestor Ironband', '', '', '', '', '', '', '', '', 0),
(8858, 'plPL', 'Sekrety kolosów – Regal', 'Nic bym tak nie chciał, jak wepchnąć tę robaczą skorupę w tłustą gębę Olejnej Pięści... Tyle że utknąłem tu, zbierając próbki z tego przerośniętego karalucha. Przy rozmiarach tego bydlaka posiedzę tu do białego rana.$B$BZanieś za mnie tę próbkę Olejnej Pięści i to migiem, $N. On płaci DUŻO!$B$BJo, Punkt Torium – jest w Płonącym Wąwozie.', 'Zanieś skorupę Kolosa z Regal nadzorcy Olejnej Pięści w Płonącym Wąwozie.$B', '', '', '', '', '', '', 0),
(13662, 'plPL', 'Zyskiwanie uznania', '', '', '', 'Wróć do mistrza kowalskiego Spopielatora w Płonącym Wąwozie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(3367, 'plPL', 'Ten list upuścił Dorius, gdy został postrzelony.', 0),
(3372, 'plPL', 'Kładziesz tajemniczy artefakt na ołtarzu Suntary.', 0),
(3377, 'plPL', 'Pogodziłem się ze swoim losem w tej klatce, ale modlitwa musi zostać odnaleziona.', 0),
(3379, 'plPL', 'Świetna robota, $N.$B$BJestem pewna, że takiego kawałka tkaniny cienia jeszcze nie $gwidziałeś:widziałaś;.', 0),
(3385, 'plPL', '$GZadałeś:Zadałaś; Podziemnemu Targowi decydujący cios. Ich przywódcy dwa razy się zastanowią, zanim wyślą do wąwozu kolejnych pachołków.$B$BA, w torbie kupca nie znalazłam niczego przydatnego. Możesz zatrzymać wszystko, co w niej znajdziesz.', 0),
(3441, 'plPL', 'Czy to ci wystarczy? Czy jesteś $ggotów:gotowa; do działania?', 0),
(3442, 'plPL', 'Dobra robota, $N. Jesteśmy prawie gotowi.', 0),
(3443, 'plPL', 'Z ciebie $gwyjątkowy robotnik:wyjątkowa robotnica;, $N. Myślisz czasem o zmianie zawodu? Może detektyw? Zbieracz złomu? O, już wiem: jeden z tych głupiutkich gnomów, co łażą po plażach Azeroth ze swoimi wykrywaczami metalu w poszukiwaniu zaginionych skarbów. Tak, to byłaby dla ciebie idealna posada.', 0),
(3452, 'plPL', 'Z symbolu bije plugawa magia; doskonale nada się do naszego zadania.', 0),
(3453, 'plPL', 'Zostało ci jeszcze jedno, ostatnie zadanie.', 0),
(3454, 'plPL', 'Chwytasz pochodnię obiema rękami; przez twoje ciało przepływają fale nienawiści i gniewu.', 0),
(3462, 'plPL', 'Czy jesteś $ggotów:gotowa; do uderzenia?', 0),
(3463, 'plPL', 'Wspaniałe! Czyż to nie wspaniałe, panie?', 0),
(3481, 'plPL', 'Skrzynia otwiera się pod twoim dotykiem. Ile sera może się w niej zmieścić? Jest tylko jeden sposób, żeby się przekonać.', 0),
(4449, 'plPL', 'O, to jest świetne! I jakie miłe w dotyku!$B$BCo? A, tak... geolodzy. $gDałeś:Dałaś; im popalić, co? Nie wiem, jak ci dziękować, $N. Teraz będę mieć trochę czasu, żeby tu skończyć... Jeszcze raz dzięki, $N.', 0),
(4451, 'plPL', 'No coś takiego! Jak u licha!? $gZnalazłeś:Znalazłaś; klucz! Wiedziałem, że ci przeklęci Czarnoryci go ukryli, jak mnie tu zamknęli! Stokrotne dzięki, $N. Jesteś $gwielki:wielka;! A teraz przekręć klucz i wypuść starego Locheeda!', 0),
(7701, 'plPL', 'Nie sządziłem, że jeszcze kiedyś zobaczę tę paszkudną gębę!$B$BSzczerze mówiąc, wygląda lepiej bez reszty szwojego czielszka.$B$BMasz tu szwoją nagrodę *hik*.', 0),
(7702, 'plPL', 'Cudownie! Ci zaspani Czarnoryci wrócą do swoich domów w Otchłani, żeby odpocząć, a to mocno spowolni pracę w Żużlowej Czeluści.', 0),
(7704, 'plPL', 'To lepsze, niż nawet ja mogłam sobie wyobrazić! Magiczna poduszka pokojówki jest moja! Możesz być $gpewien:pewna;, że za to osiągnięcie dostaniesz piękną nagrodę, $N!', 0),
(7722, 'plPL', 'Mam nadzieję, że przy okazji $gwybiłeś:wybiłaś; mu zęby, $N. Ragnaros jeden wie, że na to zasłużył.$B$BTeraz możemy przejść do rzeczy.', 0),
(7723, 'plPL', 'Dobry z ciebie $gchłopak:dziewczyna;, oj dobry. Mam dla ciebie mały prezencik za fatygę.', 0),
(7724, 'plPL', '<Hansel kicha.>$B$BChyba łapie mnie przeziębienie. Przeklęty mroźny klimat!', 0),
(7727, 'plPL', 'Oj, moje biedne nóżki.$B$BTak sobie pomyślałem, że skoro nie masz luffy...', 0),
(7728, 'plPL', 'Fantastyczna robota! A teraz twoja nagroda.', 0),
(7729, 'plPL', '15,9 funta! To może być nowy rekord wagi krwi i flaków na odzieży! Gratulacje, $N!', 0),
(7736, 'plPL', 'Ognistego topnika nigdy za wiele, młody. Przynoś dalej... chyba że każę ci przestać.', 0),
(7737, 'plPL', 'Niech ta pozostałość dalej płynie!', 0),
(8241, 'plPL', 'Ognistego topnika nigdy za wiele, młody. Przynoś dalej... chyba że każę ci przestać.', 0),
(8242, 'plPL', 'Ognistego topnika nigdy za wiele, młody. Przynoś dalej... chyba że każę ci przestać.', 0),
(8858, 'plPL', 'Znakomicie. Z tego pancerza chitynowego z pewnością zdołamy wykonać niezwykle mocną zbroję. Oto obiecane bogactwa.', 0),
(13662, 'plPL', 'Niech ta pozostałość dalej płynie!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(3367, 'plPL', 'Nie dam rady...', 0),
(3372, 'plPL', 'Ołtarz jest pusty.', 0),
(3377, 'plPL', 'Pozwól mi dokończyć opowieść.', 0),
(3379, 'plPL', 'Jakie masz informacje?', 0),
(3385, 'plPL', 'Mistrz handlu wciąż żyje?', 0),
(3441, 'plPL', 'Pozwól mi dokończyć mo...', 0),
(3442, 'plPL', 'Czy masz już materiały?', 0),
(3443, 'plPL', 'Osiem, $N. Potrzebuję ośmiu!', 0),
(3452, 'plPL', 'Bez odpowiedniego źródła energii arkanów nie da się ukończyć pochodni odwetu.', 0),
(3453, 'plPL', 'Nie przerywaj procesu przywoływania energii.', 0),
(3463, 'plPL', '$GZgubiłeś:Zgubiłaś; się, $N?', 0),
(4449, 'plPL', 'Nie mam całego dnia! Przynieś mi to jedwabne płótno! To znaczy geologów. Dopadnij tych geologów! Zasłużyli, żeby poczuć mój, no... twój gniew.', 0),
(4451, 'plPL', '*khe khe*$b$bKto tam? Nie widzisz, że jestem zajęty?', 0),
(7701, 'plPL', 'Nie widzisz, że jesztem zajęty? Czego *hik* chcesz? *hik*', 0),
(7702, 'plPL', 'Nie daj się zwieść tym szalonym goglom, $N. To ja jestem tu tą mądrą.', 0),
(7704, 'plPL', 'Ale wielka poducha! Skąd ją masz?', 0),
(7722, 'plPL', '$gZnalazłeś:Znalazłaś; plany?', 0),
(7723, 'plPL', '$gStłukłeś:Stłukłaś; ich?', 0),
(7724, 'plPL', 'Miał rację? Naprawdę strzelają z tyłków?', 0),
(7727, 'plPL', '<Hansel zawzięcie masuje swoje haluksy.>$B$BNie stój tak, weź trochę oliwy i luffę i zabierz się do szorowania tych haluksów.$B$BNie masz luffy? No to może czas, żebym posłał cię po luffę?$B$BHej, a ty dokąd?', 0),
(7728, 'plPL', 'Jeśli $gprzyszedłeś:przyszłaś; po nagrodę, musisz mi oddać skradzione rzeczy.', 0),
(7729, 'plPL', 'Dla pewności będziemy musieli zważyć cię w ubraniu i bez.', 0),
(7736, 'plPL', 'Nie marnujmy już mojego cennego czasu na gadanie. Czas skupić się na uzupełnieniu kurczących się zapasów ognistego topnika.$B$BOto, czego od ciebie potrzebuję:$B$B*Łuski incendozaurów.$B$B*Królewska krew.$B$B*Węgiel.$B$BWezmę wszystko, co możesz dać!$B$BI lepiej się pospiesz, jeśli chcesz się dobrze ustawić w Bractwie.', 0),
(7737, 'plPL', 'Udało ci się wspiąć po szczeblach korporacyjnej hierarchii Bractwa. Zaczęliśmy patrzeć na ciebie przychylnym okiem. Niezłe osiągnięcie!$B$BJeśli chcesz więcej pracy i jeszcze większego szacunku wśród nas, słuchaj uważnie.$B$BOgnisty topnik możemy uszlachetnić, dodając do mieszanki zwykłą pozostałość czarnorytu. Pozostałość czarnorytu znajdziesz w Otchłani Czarnej Góry.$B$BPrzynieś mi całą pozostałość czarnorytu, jaką znajdziesz!', 0),
(8241, 'plPL', 'Nie marnujmy już mojego cennego czasu na gadanie. Czas skupić się na uzupełnieniu kurczących się zapasów ognistego topnika.$B$BOto, czego od ciebie potrzebuję:$B$B*Łuski incendozaurów.$B$B*Sztabki żelaza.$B$B*Węgiel.$B$BWezmę wszystko, co możesz dać!$B$BI lepiej się pospiesz, jeśli chcesz się dobrze ustawić w Bractwie.', 0),
(8242, 'plPL', 'Nie marnujmy już mojego cennego czasu na gadanie. Czas skupić się na uzupełnieniu kurczących się zapasów ognistego topnika.$B$BOto, czego od ciebie potrzebuję:$B$B*Łuski incendozaurów.$B$B*Ciężka skóra.$B$B*Węgiel.$B$BWezmę wszystko, co możesz dać!$B$BI lepiej się pospiesz, jeśli chcesz się dobrze ustawić w Bractwie.', 0),
(8858, 'plPL', 'Hmmm...', 0),
(13662, 'plPL', 'Udało ci się wspiąć po szczeblach korporacyjnej hierarchii Bractwa. Zaczęliśmy patrzeć na ciebie przychylnym okiem. Niezłe osiągnięcie!$B$BJeśli chcesz więcej pracy i jeszcze większego szacunku wśród nas, słuchaj uważnie.$B$BOgnisty topnik możemy uszlachetnić, dodając do mieszanki zwykłą pozostałość czarnorytu. Pozostałość czarnorytu znajdziesz w Otchłani Czarnej Góry.$B$BPrzynieś mi całą pozostałość czarnorytu, jaką znajdziesz!', 0);
