INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3442, 'plPL', '%s intonuje coś w nieznanym języku.', '', 0),
(4345, 'plPL', 'Stój... muszę złapać.... oddech.', '', 0),
(4352, 'plPL', 'Pozwolisz, żeby ranny krasnolud odwalał za ciebie całą robotę?', '', 0),
(4353, 'plPL', 'Zaczynamy! $n, poznaj moje pięści. Pięści, oto $n.', '', 0),
(4354, 'plPL', 'To tutaj: Kocioł! Zaznacz go na mapie albo zrób cokolwiek, żeby nie zapomnieć. Gdyby coś mi się stało, moja ekipa utknęłaby w tej kopalni na zawsze.', '', 0),
(4355, 'plPL', 'Naprzód! I tym razem miej się na baczności! Nie będę już za ciebie wygrywał walk.', '', 0),
(4356, 'plPL', 'Muszę rzucić palenie! Daj mi chwilę, niech złapię oddech.', '', 0),
(4357, 'plPL', 'Jesteśmy prawie bezpieczni. Stąd biegniemy. Postaraj się nie zostawać za bardzo w tyle! BIEGIEM!', '', 0),
(4359, 'plPL', 'AAARRRGH! Dopadł mnie!', '', 0),
(4362, 'plPL', '%s znika w chmurze pyłu.', '', 0),
(4363, 'plPL', 'Widać już bramę! Uda się nam! Ale najpierw muszę odsapnąć.', '', 0),
(4380, 'plPL', '', 'Niewierni!', 0),
(4381, 'plPL', '', 'Jak śmiecie przerywać naszą modlitwę? Stracić ich!', 0),
(4382, 'plPL', '', 'Będziesz godną ofiarą dla Ragnarosa.', 0),
(4383, 'plPL', '', 'Doskonale, przybyła świeża krew.', 0),
(4400, 'plPL', 'Ołtarz zdaje się przyzywać cię, jakby był żywy.', '', 0),
(4401, 'plPL', 'Dotknij kamienia Suntary i przywołaj Lathorica Czarnego oraz jego strażnika, Obsidiona.', 'Dotknij kamienia Suntary i przywołaj Lathorica Czarnego oraz jego strażnika, Obsidiona.', 0),
(4413, 'plPL', 'Raze musieć już iść do domu. Pa, pa, $r.', '', 0),
(4415, 'plPL', 'Pa, pa, mały malutki $r. Raze już iść.', '', 0),
(4429, 'plPL', 'Pomsta należy do mnie.', '', 0),
(4430, 'plPL', 'Powiedz, co napędza tę pomstę?', 'Powiedz, co napędza tę pomstę?', 0),
(4431, 'plPL', 'Mojego ojca zabiło plugastwo, które zamieszkuje Kocioł. Moje prośby o pomoc skierowane do wichrogrodzkiego magistratu trafiły w próżnię. O nie, oni nie chcą nawet przyznać, że ta część świata istnieje, a co dopiero wysłać tu swoje cenne wojsko, by wymierzyło sprawiedliwość.$B$BSzukam pomsty, tak po prostu. Czy jest na tym świecie sprawa, która budzi większą namiętność?', '', 0),
(4433, 'plPL', 'Jak widzisz, jestem tylko jednym człowiekiem z niezdarnym osiłkiem w roli giermka. Potęga krasnoludów Czarnorytych i bestii trzymanych w garści przez Ragnarosa z pewnością by mnie w pojedynkę przytłoczyła, ale jestem głęboko przekonany, że $gtak dzielny i ambitny poszukiwacz:tak dzielna i ambitna poszukiwaczka; przygód jak ty bez trudu poradzi sobie z mieszkańcami Kotła. Jeśli zechcesz mi pomóc, wynagrodzę cię bogactwem przekraczającym twoje najśmielsze marzenia.', '', 0),
(4434, 'plPL', 'Pozwól, że naradzę się z towarzyszami.', 'Pozwól, że naradzę się z towarzyszami.', 0),
(4447, 'plPL', '%s intonuje coś w nieznanym języku.', '', 0),
(4448, 'plPL', 'Cierpliwości, $n. Pochodnia jest prawie gotowa.', '', 0),
(4449, 'plPL', '%s pada na jedno kolano. Wygląda na wyczerpanego.', '', 0),
(4450, 'plPL', 'Stało się...', '', 0),
(4459, 'plPL', 'Co z nimi zrobimy, panie? Już nam się do niczego nie przydadzą.', '', 0),
(4468, 'plPL', 'Już się robi, panie!', '', 0),
(4521, 'plPL', 'Raze iść za $n! Raze MIAŻDŻYĆ kłusowniki! MIAŻDŻYĆ MIAŻDŻYĆ MIAŻDŻYĆ! Machać kijem, mówić Raze MIAŻDŻYĆ! MIAŻDŻYĆ!', '', 0),
(4624, 'plPL', 'Żyję tylko po to, by służyć panu.', '', 0),
(5304, 'plPL', 'Czego chcieć od Raze??', '', 0),
(5306, 'plPL', 'Potrzebuję pomocy w pokonaniu kłusowników Cienistego Jedwabiu.', 'Potrzebuję pomocy w pokonaniu kłusowników Cienistego Jedwabiu.', 0),
(5409, 'plPL', 'Halo?', '', 0),
(5410, 'plPL', 'Eee... przepraszam, że przeszkadzam, ale czy mogę jeszcze raz zobaczyć księgę rachunkową Dobrostala... jeśli z niej nie korzystasz.', 'Eee... przepraszam, że przeszkadzam, ale czy mogę jeszcze raz zobaczyć księgę rachunkową Dobrostala... jeśli z niej nie korzystasz.', 0),
(5411, 'plPL', 'Jasne, nie ma sprawy, $n! Wybacz... zdawało mi się, że już z nią $gskończyłeś:skończyłaś;.', '', 0),
(5944, 'plPL', '%s wskazuje pergamin leżący na ziemi.', '', 0),
(5949, 'plPL', 'Użyć kij, mówić Raze, co robić! Pokazać Raze kłusownik! Raze miażdżyć!', '', 0),
(6293, 'plPL', '', 'O, cześć! Jestem Sarah. W czym mogę pomóc?', 0),
(7773, 'plPL', 'Kalaranie, $gzgubiłem:zgubiłam; pochodnię. Potrzebuję nowej.', 'Kalaranie, $gzgubiłem:zgubiłam; pochodnię. Potrzebuję nowej.', 0),
(9023, 'plPL', 'Kalaranie, proszę, zaczaruj pochodnię.', 'Kalaranie, proszę, zaczaruj pochodnię.', 0),
(9798, 'plPL', 'Tak, to prawda, jesztem ślepy jak kret! I pijany jak... eee, pijany jak coś, co sie upija.$B$BPowiem ci coś. To gorzałka trzyma moje zmyszły w gotowości. Wszyszcy wiedzą, że jak tracisz jeden zmyszł, to inne zmyszły robią sie czujniejsze. Mój zmyszł pijaństwa jeszt ostatnio niesamowity.', '', 0),
(9811, 'plPL', '', 'Postanowiliśmy porzucić ochronę i wygody Otchłani, by eksploatować... eee, to znaczy... hmm, tak, właśnie, EKSPLOROWAĆ świat.', 0),
(9819, 'plPL', 'Spopielator się nazywam, kucie to moja działka... i, eee... na boku sprzedaję też trochę jedzenia i wody. Skusisz się na mięsko?', '', 0),
(9821, 'plPL', 'Kiedy Lolo nie chce rozlać swojego cennego piwa ani pobrudzić swojej sukieneczki, wołają mnie. Tak jest. Stary Hansel to krasnolud od wymierzania odrobiny sprawiedliwości i całej masy bólu.', '', 0),
(9824, 'plPL', 'Jako pełniący obowiązki poganiacza tego obozu mam obowiązek dopilnować, by wszelkie interesy, praca, odpoczynek i rozrywka, jakie mogą się tu odbywać, wiązały się z odpowiednią dozą mitręgi.$B$BJeśli cokolwiek, o co cię poproszono, wyda ci się zbyt łatwe i bezproblemowe, natychmiast zgłoś się do mnie.', '', 0),
(9825, 'plPL', '$GZrobiłeś:Zrobiłaś; wszystko, o co cię prosiłem, $n. Tutaj naprawdę nic więcej dla ciebie nie ma. Jeśli chcesz kontynuować karierę jako $gagent:agentka; Bractwa Torium, porozmawiaj z Lokhtosem Ciemnotargiem w karczmie „Pod Ponurym Opojem” w Otchłani Czarnej Góry.$B$BBywaj!', '', 0),
(9828, 'plPL', '', 'Bractwo Torium czy nie, jak któryś z tych Czarnorytych się do mnie zbliży, posmakuje mojego oskarda na boku łba! No, dokąd cię wysłać, $Gchłopcze:dziewczyno;?', 0),
(9841, 'plPL', '', 'Dopóki te krasnoludy siedzą tam, gdzie siedzą, nie będziemy mieć kłopotów. Dokąd się wybierasz, $n?', 0),
(11397, 'plPL', 'W tę Zimową Ucztę nakarmię was moim ostrzem! Jaargh!', 'W tę Zimową Ucztę nakarmię was moim ostrzem! Jaargh!', 0),
(11398, 'plPL', 'Żaden obwieś nie zabierze nam łupów z Zimowej Uczty! Brać ich!', 'Żaden obwieś nie zabierze nam łupów z Zimowej Uczty! Brać ich!\n', 0),
(11399, 'plPL', 'Te szczury lądowe przyszły po renifera! Pod żebro ich!', 'Te szczury lądowe przyszły po renifera! Pod żebro ich!\n', 0),
(11400, 'plPL', 'To próba odbicia! Niech nikt nie ucieknie!', 'To próba odbicia! Niech nikt nie ucieknie!\n', 0),
(11401, 'plPL', 'Przekażę ci moje pozdrowienia dla Praojca Mroza, szumowino...', 'Przekażę ci moje pozdrowienia dla Praojca Mroza, szumowino...\n', 0),
(11402, 'plPL', 'Brednie! Giń!', 'Brednie! Giń!\n', 0),
